package android.app;import java.util.*;public class NotificationManager {public static final int IMPORTANCE_NONE=0,IMPORTANCE_DEFAULT=3;public boolean allowed=true;public int notified=0,cancelled=0,lastId;public Notification last;public final Map<String,NotificationChannel> channels=new HashMap<>();public NotificationChannel getNotificationChannel(String id){return channels.get(id);}public void createNotificationChannel(NotificationChannel c){channels.put(c.id,c);}public boolean areNotificationsEnabled(){return allowed;}public void notify(int id,Notification n){notified++;lastId=id;last=n;}public void cancel(int id){cancelled++;}}
